#include <MHZ19.h>
HardwareSerial mhSerial(1);
MHZ19 mh;
void setup() {
    Serial.begin(115200);
    mhSerial.begin(9600, SERIAL_8N1, {{rx_pin}}, {{tx_pin}});
    mh.begin(mhSerial);
    mh.autoCalibration();
}
void loop() {
    Serial.printf("CO2=%d ppm T=%d\n", mh.getCO2(), mh.getTemperature());
    delay(2000);
}
